"""Shared export pipeline for the CSV and JSON exporters.

``export_rows`` is the single entry point. It validates the format first,
then normalizes the rows once and serializes them. The public wrappers in
``csv_exporter`` and ``json_exporter`` delegate here.
"""

import csv
import io
import json

_FIELDS = ("id", "name")


def _to_text(value):
    return "" if value is None else str(value)


def _normalize(rows):
    """Return a new list of ``{"id": str, "name": str}`` dicts in input order.

    Only the fields in ``_FIELDS`` are kept. Missing or ``None`` values become
    ``""``; anything else is stringified. ``rows`` is iterated exactly once, so
    one-shot iterables work, and neither ``rows`` nor its items are modified.
    """
    return [{key: _to_text(row.get(key)) for key in _FIELDS} for row in rows]


def _serialize_csv(records):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(_FIELDS)
    for record in records:
        writer.writerow([record[key] for key in _FIELDS])
    return buffer.getvalue()


def _serialize_json(records):
    return json.dumps(records, ensure_ascii=False, separators=(",", ":"))


def export_rows(rows, format):
    """Export ``rows`` (dict-like, each with optional ``id``/``name``) as ``format``.

    ``format`` is ``"csv"`` or ``"json"``. Any other value raises ``ValueError``
    before ``rows`` is consumed.
    """
    if format == "csv":
        serialize = _serialize_csv
    elif format == "json":
        serialize = _serialize_json
    else:
        raise ValueError("unsupported format")
    return serialize(_normalize(rows))
